[
  {
    "statement": "Various modifications to trawl gear have been studied for their effectiveness in reducing unwanted fish catch.",
    "citations": []
  },
  {
    "statement": "Modifying trawl gear, such as changing trawl wires, the number of nets, codend, or footrope configuration, has been found to reduce unwanted catches of non-target or discarded fish species and sizes.",
    "citations": [
      "2704"
    ]
  },
  {
    "statement": "Trawl gear modifications have been found to improve the size-selectivity for unwanted fish.",
