    "citations": [
      "2692"
    ]
  },
  {
    "statement": "The post-release movements of tracked whale sharks released from purse seines using an enhanced protocol appeared normal.",
    "citations": [
      "2692"
    ]
  },
  {
    "statement": "One study in the Pacific Ocean found that reef fish returned more quickly to a reef or the seabed after release when using protocols with minimal handling and air exposure, compared to higher stress handling and longer air exposure.",
    "citations": [
      "2692"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of implementing vessel decommissioning schemes on marine fish populations.",
    "citations": [
      "3821"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of using human observers onboard fishing vessels to monitor catches and discards on marine fish populations.",
    "citations": [
      "2740"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of introducing fishing permit, licence or charter schemes on marine fish populations.",
