    "citations": [
      "2735"
    ]
  },
  {
    "statement": "A global review found that recruitment in four of five swordfish fisheries was either highly variable or could not be assessed.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "A study in the Ionian Sea found that despite minimum sizes, most commercially landed fish were immature.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of setting a maximum landing size for commercially fished species.",
    "citations": [
      "2736",
      "2737"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of specifying a capture size range for commercially fished species.",
    "citations": [
      "2736",
      "2737"
    ]
  }
]

[
  {
