    ]
  }
]

[
  {
    "statement": "Prohibiting all mobile and static fishing gears that target bottom-dwelling species led to a higher abundance of larger and older cod.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Fish densities in areas closed to all mobile and static fishing gears for at least 11 years varied between species, depth, and temperature.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "In areas closed to all mobile and static fishing gears, no change in fish densities was observed after 2–7 years.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "Cod growth was better in areas closed to all mobile and static fishing gears for 5–15 years.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "In areas closed to all mobile and static fishing gears, fish size varied.",
