    ]
  },
  {
    "statement": "Prohibiting seine nets led to higher overall fish catch rates.",
    "citations": [
      "2673"
    ]
  },
  {
    "statement": "In an area where all but one gear type was prohibited, a higher fish density was observed compared to other areas.",
    "citations": [
      "3810"
    ]
  },
  {
    "statement": "A combination of prohibiting non-selective gear types and long-term closures reduced the unwanted catch of cod.",
    "citations": [
      "3810"
    ]
  }
]

[
  {
    "statement": "A study in the USA found that using modified crab pots with mesh chimneys reduced the mortality of diamondback terrapins.",
    "citations": [
      "3622"
    ]
  },
  {
    "statement": "A study in the Indian Ocean (South Africa) found that prohibiting offshore line fishing in a marine protected area resulted in higher abundances and larger sizes of four over-exploited fish species.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of prohibiting the catching and/or landing of specific fish species on marine fish populations.",
    "citations": [
      "3822"
    ]
  }
]

[
  {
    "statement": "A review of six studies found the majority (76-92%) of discarded or protected small-spotted catshark, thorny skate, pearl perch, and Atlantic wolffish survived for at least 1 hour to 5 days after capture.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "A review found that less than half of smooth skate survived after capture.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Fish survival was found to be reduced by hooking or capture depth injuries.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Fish survival was found to be reduced by longer tow durations.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "One study showed that nearly all yelloweye rockfish survived for four days after capture.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "The survival of canary rockfish decreased with increasing capture depth.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "All spinetail devilrays that were brailed aboard from purse seine nets survived.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "Spinetail devilrays brought aboard entangled in a purse seine net did not survive.",
    "citations": [
      "2691"
    ]
  },
  {
    "statement": "A global review of longline fishing indicated that using nylon hook attachment lines instead of wire resulted in higher survival for two out of three shark and ray species.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "A global review of longline fishing indicated that using nylon hook attachment lines instead of wire resulted in lower survival for one shark and ray species.",
    "citations": [
      "2699"
    ]
  },
  {
    "statement": "A study in the Atlantic Ocean found that the survival of unwanted sharks caught on tuna longlines was reduced with nylon hook lines compared to wire hook lines.",
    "citations": [
      "2699"
    ]
  }
]

[
  {
    "statement": "The effects of prohibiting fishing on fish abundance vary across different ocean basins.",
    "citations": []
  },
  {
    "statement": "In marine protected areas across the Indian, Atlantic, Mediterranean, Pacific, Tasman, Coral, Philippine, Caribbean, Gulf of Mexico, and Sulu Seas, 30 of 54 studies found higher fish abundances.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "The effect of prohibiting fishing can differ based on factors like species, the species' position in the food chain, and habitat.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Other studies found varied effects or similar abundances between fished and protected areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "After prohibiting all commercial fishing, two of four studies in the Mediterranean Sea, Indian Ocean, South Atlantic Ocean, and Gulf of Mexico reported higher abundances for some species.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A study in the South China Sea noted an increase in overall fish density in the region surrounding new marine reserves.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "A study in a Tasman Sea estuary observed a lower abundance for most fish species two years after the area was closed to fishing.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South Pacific Ocean, prohibiting commercial lobster fishing did not lead to an increase in lobster abundance over 12 years.",
    "citations": [
      "2225"
    ]
  }
]

[
  {
    "statement": "Setting catch limits or quotas for non-commercially targeted fish reduced unwanted catch in two of three cases in the Atlantic and Pacific Oceans.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "A study in the Pacific Ocean found that catch limits for non-target commercial species reduced the amount of unwanted halibut.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "Using a different bait type reduced the unwanted catches of undersized haddock, Atlantic cod and other unwanted or non-target fish in six of eight studies.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Two studies found no reduction in unwanted catches of pelagic stingray and overall unwanted fish with different bait types.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Two systematic global reviews found that using different bait types did not affect the number of unwanted sharks and rays caught.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "One study found that using a different bait species increased the size-selectivity of commercially targeted Greenland halibut.",
    "citations": [
      "2700"
    ]
  }
]

[
  {
    "statement": "A study in the North Sea indicated that after vessels with higher engine power were excluded from an area for half of each year, there was a higher abundance of commercially targeted fish.",
    "citations": [
      "3809"
    ]
  },
  {
    "statement": "The same study showed there was no difference in the overall abundance of non-commercially targeted fish over five years.",
    "citations": [
      "3809"
    ]
  }
]

[
  {
    "statement": "Three studies were found that examined the effect of involving fishers and stakeholders in co-management of marine fish populations.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "One study in the Indian Ocean found that involving fishers and stakeholders in co-management increased overall fish abundance.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "A study in the Pacific Ocean found no decrease in overall fishing effort.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "A study in the Pacific Ocean found no increase in total fish catch rates.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "A study in the South China Sea reported a decrease in illegal fishing using destructive fishing gears after co-management was established.",
    "citations": [
      "2910"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of engaging fishers in scientific data collection on marine fish populations.",
    "citations": [
      "2813"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of involving stakeholders in the allocation of harvest rights on marine fish populations.",
    "citations": [
      "2812"
    ]
  }
]

[
  {
    "statement": "A review in the North Pacific and North Atlantic Oceans found that using technology to provide near real-time catch information to fishers resulted in reductions in unwanted catch or discards.",
    "citations": [
      "3826"
    ]
  },
  {
    "statement": "The reductions in unwanted catch or discards occurred in two of three cases.",
    "citations": [
      "3826"
    ]
  }
]

[
  {
    "statement": "The use of different hook types in longline or recreational fisheries is an alternative management strategy.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Studies have shown that modifying hook type, including size and style, can reduce the incidence of injuries and capture mortality for some unwanted sharks, rays, and billfish species when compared to conventional hooks.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "The use of different hook types has been found to reduce the unwanted catch of non-commercially targeted and small non-target fish species.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Increasing hook size can improve the size-selectivity for certain species by increasing the average catch length.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Some studies found that changing hook type did not reduce the capture mortality of other non-target species.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "Some studies found that changing hook type did not reduce the unwanted catch of young or non-target fish.",
    "citations": [
      "2698"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on marine fish populations of purchasing fishing permits to limit vessel or fisher numbers.",
    "citations": [
      "3818"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects on marine fish populations of specifying a size range for commercially fished species.",
    "citations": [
      "2737"
    ]
  }
]

[
  {
    "statement": "Unspecified fishing restrictions in marine protected areas have been studied for their effects on marine fish and invertebrate populations.",
    "citations": [
      "2680",
      "2239"
    ]
  },
  {
    "statement": "For marine fish, the introduction of unspecified fishing restrictions within a marine protected area has been shown to result in higher fish species richness inside the reserves compared to areas without fishing restrictions.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "The introduction of unspecified fishing restrictions within a marine protected area has been shown to result in higher fish abundance inside the reserves compared to areas without fishing restrictions.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "Fish inside marine protected areas with unspecified fishing restrictions were found to be of a larger average size.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "For invertebrate populations, marine protected areas with some fishing restrictions were found to have more lobsters, scallops, sea cucumbers, hydrozoans, and sponges when compared to fished areas.",
    "citations": [
      "2239"
    ]
  }
]

[
  {
    "statement": "Modifications to trawl gear, such as changes to the length of the extension piece, the codend strengthening bag, the method of weaving, the number of codend layers, and overall design, improved the size-selectivity for unwanted fish species or sizes.",
    "citations": [
      "2704"
    ]
  },
  {
    "statement": "Changes to trawl wires, number of nets, codend number, footrope configuration, front trawl body panels, spreading mechanism, knot orientation, or using a new overall trawl design resulted in reduced unwanted catches of non-target and/or discarded fish species or sizes.",
    "citations": [
      "2704"
    ]
  },
  {
    "statement": "Turning the orientation of diamond mesh in trawl codends by 90° resulted in better size selection of cod, red mullet, common pandora, and round-bodied fish species compared to standard orientation of diamond mesh in trawl codends.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "Turning the orientation of diamond mesh in trawl codends by 90° did not result in better size selection of plaice, annular sea bream, and flatfish species compared to standard orientation of diamond mesh in trawl codends.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "Using turned mesh instead of standard diamond mesh trawl codends did not improve the size selectivity of cod, plaice and flounder.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "Reducing the size of the main body of a trawl net did not improve the size-selection of cod and haddock.",
    "citations": [
      "2705"
    ]
  }
]

[
  {
    "statement": "A study in the Indian Ocean indicated that prohibiting offshore line fishing and other boat-based fishing within a marine protected area resulted in a greater abundance and larger sizes of four over-exploited fish species.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "Six of eight replicated studies found that using different bait types, such as variations in size, species, and manufacturing method, led to a reduction in unwanted catches of undersized haddock, Atlantic cod, and other non-target fish.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Two other studies found no decrease in the unwanted catches of pelagic stingray and other fish when using different bait types.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Two global systematic reviews found that altering bait types did not impact the number of unwanted sharks and rays caught.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "One replicated study and one global systematic review showed that different bait species did not lessen hooking injuries in undersized snapper or sharks and rays.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Different bait species did not improve the survival rate of sharks and rays when the gear was retrieved, according to one replicated study and one global systematic review.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "A replicated study in the Denmark Strait revealed that using a different bait species enhanced the size-selectivity of fishing gear for commercially targeted Greenland halibut.",
    "citations": [
      "2700"
    ]
  }
]

[
  {
    "statement": "In prawn and shrimp trawl fisheries, gear modifications are available to reduce the unwanted catch of fish.",
    "citations": []
  },
  {
    "statement": "Shrimp trawls fitted with a mesh size-sorting funnel, or sieve net, reduced the catches of unwanted, non-commercial, or discarded fish compared to standard trawls.",
    "citations": [
      "2722"
    ]
  },
  {
    "statement": "Using a topless trawl reduced the catch of unwanted Atlantic cod and discards of commercial fish species compared to conventional trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Using a topless trawl in combination with another non-conventional trawl type reduced the catch of unwanted Atlantic cod and discards of commercial fish species.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls reduced unwanted catches of larger haddock compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Topless trawls did not reduce unwanted catches of smaller haddock compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "In some cases, topless trawls reduced unwanted catches of larger Atlantic cod compared to standard trawl types.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Four designs of W-trawl nets used in shrimp/prawn fisheries caught less non-commercial unwanted catch of crustaceans compared to a traditional Florida Flyer trawl net.",
    "citations": [
      "2139"
    ]
  }
]

[
  {
    "statement": "Modifying the configuration of gillnets, such as reducing the gillnets' height, increasing tension, twine diameter, mesh size, and altering orientation, has been found to reduce the unwanted catch of cod and other discarded commercial and non-commercial species.",
    "citations": [
      "2701"
    ]
  },
  {
    "statement": "One study noted that gillnet modification did not typically reduce unwanted shark catches.",
    "citations": [
      "2701"
    ]
  },
  {
    "statement": "For fishing traps and pots, modifications such as using a different trap type, increasing mesh size, or fitting an escape device have been shown to reduce unwanted catches of various species including brown trout, black sea bass, herring, cod, protected rockfishes, sharks, and rays.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Using square mesh escape windows or larger mesh sizes can improve the size-selectivity for species like Atlantic cod and black sea bass.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Some studies found that trap modifications had no effect on the unwanted catches of white croaker and undersized Atlantic cod.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "In one case, trap modifications increased the bycatch of haddock.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Changing the type of bait, including the bait's size, species, and manufacturing method, has been found to reduce unwanted catches of undersized haddock and Atlantic cod.",
    "citations": [
      "2700"
    ]
  },
  {
    "statement": "Other studies found that different bait types did not reduce the unwanted catches of pelagic stingrays, other fish, sharks, or rays.",
    "citations": [
      "2700"
    ]
  }
]

[
  {
    "statement": "Four designs of W-trawl nets used in shrimp/prawn fisheries were found to catch less non-commercial unwanted crustaceans compared to a traditional Florida Flyer trawl net in one study in Moreton Bay, Australia.",
    "citations": [
      "2139"
    ]
  },
  {
    "statement": "The four designs of W-trawl nets also caught lower amounts of the commercially targeted prawn species.",
    "citations": [
      "2139"
    ]
  },
  {
    "statement": "In the North Sea, three studies found that shrimp trawls fitted with a size-sorting mesh funnel, or sieve net, reduced the catches of unwanted and non-commercial or discarded fish compared to standard trawls.",
    "citations": [
      "2722"
    ]
  },
  {
    "statement": "Two out of four studies in the North Sea, Gulf of Maine, and Baltic Sea found that using a topless trawl reduced the catch of unwanted Atlantic cod and discards of commercial fish species when compared to conventional trawls.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Another study showed that topless trawls reduced unwanted catches of larger haddock and, in one of two cases, larger Atlantic cod.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "A fourth study found that topless trawls reduced discarded catches of one of four commercial fish species.",
    "citations": [
      "2712"
    ]
  }
]

